from pathlib import Path
from html import escape as esc
import json

OUT = Path(__file__).parent
data = json.loads((OUT/'phone-camera-mechanics.json').read_text())
theme = (OUT.parent/'src/styles/theme.css').read_text()
labels = {'capture':'Захват','pixels':'Пиксели','ml':'CV / ML','device':'Проверка устройства','custom':'Своя обработка','prop':'Реквизит','ocr':'OCR','code':'Коды','marker':'Метки / эталоны','ar':'AR','depth':'Глубина','experimental':'Эксперимент','reconstruction':'3D-реконструкция','generative':'Генерация','network':'Сеть / синхронизация','hybrid':'Гибрид','audio':'Микрофон','geo':'Геопозиция'}
families = ''.join(f'<option value="{g["id"]}">{esc(g["title"])}</option>' for g in data['groups'])
tags = ''.join(f'<option value="{k}">{esc(v)}</option>' for k,v in labels.items())
nav = ''.join(f'<a href="#{g["id"]}"><span>{n:02d}</span>{esc(g["title"])}<small>8</small></a>' for n,g in enumerate(data['groups'],1))
sections = []
for n, g in enumerate(data['groups'], 1):
    rows = []
    for item in g['items']:
        assert all(t in labels for t in item['tech'])
        badges = ''.join(f'<span class="tag {"special" if t in ["experimental","device"] else ""}">{labels[t]}</span>' for t in item['tech'])
        searchable = esc(' '.join([g['title'],item['name'],item['interaction'],item['application'],*[labels[t] for t in item['tech']]]), quote=True)
        rows.append(f'''<tr id="{item['id']}" data-tags="{' '.join(item['tech'])}" data-search="{searchable}">
<th scope="row"><a class="row-id" href="#{item['id']}">{item['id']}</a><strong>{esc(item['name'])}</strong><div class="tags">{badges}</div></th>
<td data-label="Действие и правило">{esc(item['interaction'])}</td><td data-label="Применение">{esc(item['application'])}</td></tr>''')
    refs = ' · '.join(f'<a href="{data["sources"][s]["url"]}" target="_blank" rel="noopener">{esc(data["sources"][s]["title"])}</a>' for s in g['sources'])
    sections.append(f'''<section class="family" id="{g['id']}" data-family="{g['id']}"><div class="section-heading"><span class="section-number">{n:02d}</span><div><h2>{esc(g['title'])}</h2><p>{esc(g['intro'])}</p></div><span class="family-count">8</span></div>
<p class="caution"><b>Условие реализации.</b> {esc(g['caution'])}</p>
<table><caption class="sr-only">{esc(g['title'])}: действие, правило и применение</caption><thead><tr><th scope="col">Механика</th><th scope="col">Действие и правило</th><th scope="col">Применение</th></tr></thead><tbody>{''.join(rows)}</tbody></table>
<p class="family-sources"><b>Техническая основа:</b> {refs}</p></section>''')
references = ''.join(f'<li><a href="{s["url"]}" target="_blank" rel="noopener">{esc(s["title"])}</a></li>' for s in data['sources'].values())
payload = json.dumps(data,ensure_ascii=False).replace('</','<\\/')

